import { Link } from "react-router-dom";
import "./Sidebar.css";

export default function Sidebar() {
  return (
    <div className="sidebar">
      <h3>תפריט</h3>
      <ul>
        <li><Link to="/">דף הבית</Link></li>
        <li><Link to="/report1">דוח 1</Link></li>
        <li><Link to="/report2">דוח 2</Link></li>
        <li><Link to="/report3">דוח 3</Link></li>
        <li><Link to="/report4">דוח 4</Link></li>
        <li><Link to="/report5">דוח 5</Link></li>
      </ul>
    </div>
  );
}
